# -*- coding: utf-8 -*-
"""Правки ценностного предложения по находкам критика 21.09 (сегмент против данных).
Каждая замена — точная, с проверкой, что исходная строка встречается ровно один раз."""
import io

P = "2026-09-21_segment-a-value-proposition.html"
s = io.open(P, encoding="utf-8").read()
n = 0


def rep(old, new):
    global s, n
    assert s.count(old) == 1, (old[:90], s.count(old))
    s = s.replace(old, new)
    n += 1


rep("пары, которые скидываются на крупное из своих денег · запуск",
    "пары с раздельными деньгами и крупной общей покупкой впереди · запуск")
rep('<p class="big">Скинуться на крупную общую покупку к дате — и не открывать партнёру свои деньги.</p>',
    '<p class="big">Понять, сойдётся ли крупная покупка к дате и сколько останется на себя, — не открывая партнёру свои деньги.</p>')
rep("Для пар, у которых у каждого свои деньги, а на крупное — котёл, кровать, ремонт, отпуск — они договариваются и скидываются со своих карт в разных банках.",
    "Для пар, у которых у каждого свои деньги в разных банках, а крупное — котёл, ремонт, кровать — обсуждают заранее: хватит ли к сроку и кто платит. Скидываются долями или платит один — продукту всё равно.")
rep("Сейчас такая пара прикидывает в голове и в разговоре, «кто может сколько скинуть, у кого какие приходы», а до даты каждый сам следит, успевает ли.",
    "Сейчас такая пара прикидывает в голове и в разговоре, хватит ли к сроку и кто платит, а до даты каждый сам следит, успевает ли.")
rep('<span class="tag t-back">2 из 3 пар A не хотят показывать всё</span>: «у каждого должна быть своя некая подушка безопасности» (P09); «есть траты, которые я не хотел бы показывать жене» (P08).',
    '<span class="tag t-der">1 из 3 без подсказки, 1 из 3 — в ответ на рассказ идеи</span>: «у каждого должна быть своя некая подушка безопасности» (P09, до рассказа идеи; рядом — «я в любом случае знаю, сколько он тратит»); «есть траты, которые я не хотел бы показывать жене» (P08, после рассказа о полной видимости).')
rep('<li><b>Видно, сойдётся ли сумма к дате — и сколько останется у меня.</b> <span class="tag t-back">3 из 3</span>: «прикидываем, кто может сколько скинуть, у кого тогда какие приходы» (P08); «не могу рассчитать, сколько потрачу до конца» (P04, важность 7–8 из 10); «сколько мне нужно, сколько я могу выделить» (P09).</li>',
    '<li><b>Видно, сойдётся ли сумма к дате — и сколько останется у меня.</b> <span class="tag t-back">сойдётся к дате — 2 из 3; сколько могу выделить сам — 2 из 3</span>: «супермега положительный результат, когда сходится, и время» (P04); «прикидываем, кто может сколько скинуть, у кого тогда какие приходы» (P08); «не могу рассчитать, сколько потрачу до конца» (P04-B); «сколько мне нужно, сколько я могу выделить» (P09, про свою покупку).</li>')
rep("«я же самостоятельная женщина, а тут я должна кого-то просить и ещё ждать» (P09)",
    "«я же самостоятельная женщина… а тут я должна кого-то просить о чём-то и ещё ждать» (P09, про мелкие просьбы, не про крупное)")
rep("<b>общего котла нет, но крупное общее они покупают, скидываясь</b>. «У каждого бабки залетели — это его бабки… на эти траты мы договариваемся и скидываемся» (P08).",
    "<b>общего котла нет, а крупное общее обсуждают заранее</b> — хватит ли к сроку и кто платит. Долями скидывается одна пара из трёх: «на эти траты мы договариваемся и скидываемся» (P08); в двух других крупное оплачивает один: «либо я покупаю, либо [муж]» (P04), «отпуск закрывает он» (P09).")
rep("Признак для отбора — один вопрос: <i>«Как вы делили последнюю крупную покупку?»</i> Ответ «скинулись» — наш сегмент.",
    "Признак для отбора — один вопрос: <i>«Как вы решали последнюю крупную покупку?»</i> Ответы «скинулись» и «обсудили, и заплатил один» — наш сегмент; «не обсуждали» и «с общего счёта» — нет.")
rep("Для пар с раздельными деньгами, которые скидываются на крупные общие покупки, Finance Assistant — это веб-приложение, которое из одной фразы собирает общую покупку с долями и показывает каждому, успевает ли его доля к дате.",
    "Для пар с раздельными деньгами, у которых впереди крупная общая покупка, Finance Assistant — это веб-приложение, которое из одной фразы собирает покупку и показывает, сойдётся ли она к дате, сколько откладывать и сколько остаётся на себя; доли — если платят оба.")
rep("<li>Крупное общее обсуждают заранее: сумма, срок, кто сколько внесёт — 3 из 3.</li>",
    "<li>Крупное общее обсуждают заранее: сумма, срок, кто платит — 2 из 3 (P04, P08). Скидываются долями — 1 из 3 (P08); в P04 и P09 крупное оплачивает один партнёр.</li>")
rep("<li>Не хотят видеть всё у партнёра и показывать всё своё — 2 из 3 (в P04 полную видимость не предлагали).</li>",
    "<li>Не хотят показывать партнёру всё — 1 из 3 без подсказки (P09), ещё 1 — в ответ на рассказ идеи (P08); в P04 полную видимость не предлагали.</li>")
rep("хочу договориться, кто сколько внесёт к дате, так, чтобы своё осталось своим и было видно, сколько останется у меня, — чтобы купить вместе и не поссориться.</i> <span class=\"tag t-back\">3 из 3 пар A</span>",
    "хочу понять, сойдётся ли сумма к дате и сколько останется у меня, — а если платим оба, договориться, кто сколько внесёт, — так, чтобы своё осталось своим, чтобы купить вместе и не поссориться.</i> <span class=\"tag t-der\">обсуждают заранее — 2 из 3; долями — 1 из 3</span>")
rep('<td>умственная нагрузка, месяц неопределённости</td><td><span class="tag t-back">3 из 3 A</span></td>',
    '<td>умственная нагрузка, месяц неопределённости</td><td><span class="tag t-back">2 из 3 A</span></td>')
rep('<td>страх, отказ на первом шаге</td><td><span class="tag t-back">2 из 3 A</span></td>',
    '<td>страх, отказ на первом шаге</td><td><span class="tag t-der">1 из 3 о себе (P08), 1 — о других людях (P04-B)</span></td>')
rep("<p><b>Порядок приоритетов:</b> автономия → предсказуемость → без ссор.",
    "<p><b>Порядок приоритетов:</b> автономия → предсказуемость → без ссор — <span class=\"tag t-hyp\">выведено</span>: по-парного порядка в данных нет, критерии распределены по разным парам (автономия — P08, P09; предсказуемость — P04, P09).")
rep("<td>прикинуть, кто сколько может внести</td><td>по приходам каждого</td><td>считают в голове, свои приходы открывать не хотят · 7</td><td><b>разрыв:</b> умственная нагрузка + приватность</td>",
    "<td>прикинуть, хватит ли и кто сколько (или кто один) платит</td><td>по приходам каждого</td><td>считают в голове · 7</td><td><b>разрыв:</b> умственная нагрузка</td>")
rep("<td>Пары, которые скидываются на крупное, есть среди приходящих: 25%+ отвечают «скинулись» на вопрос о последней крупной покупке</td>",
    "<td>Пары с раздельными деньгами и крупной покупкой есть среди приходящих: 25%+ отвечают «скинулись» или «обсудили, и заплатил один» на вопрос о последней крупной покупке</td>")
rep("— задача есть у 3 из 3, но привычка разговора — у 9 из 9.",
    "— крупное заранее обсуждают 2 из 3, привычка разговора — у 9 из 9.")
rep("«Виртуальный кошелёк под каждую цель, куда деньги переводятся физически» — P08-B. Это по одному голосу, а не закономерность.",
    "Это по одному голосу, а не закономерность.</p>\n<p><b>Важная оговорка.</b> Единственная пара, которая скидывается долями (P08), сама предложила «под каждую цель открывать виртуальный кошелёк и тогда сразу бабки перекидывать». То есть она просит ровно то, что уже делают копилки банков. Отличие «план до перевода денег» для неё не доказано — проверить в проверке удобства вопросом «пробовали сбор или копилку в банке?».")
rep("задача взята у сегмента, а не у продукта — да, 3 из 3;",
    "задача взята у сегмента, а не у продукта — да, но опора тоньше, чем казалось: обсуждают заранее 2 из 3, долями — 1 из 3 (исправлено после критика 21.09);")
# ранжирование: уверенность H1 0,60 → 0,40
rep('<td>Общая покупка: сумма, дата, у каждого своя доля; партнёр видит только общий прогресс</td><td>1.00</td><td>3</td><td>0.60</td><td>1.50</td><td>+2</td><td>3.20</td><td><span class="tag t-der">задача 3 из 3 A</span></td>',
    '<td>Общая покупка: сумма, дата, у каждого своя доля; партнёр видит только общий прогресс</td><td>1.00</td><td>3</td><td>0.40</td><td>1.50</td><td>+2</td><td>2.80</td><td><span class="tag t-der">обсуждают заранее 2 из 3, долями 1 из 3</span></td>')
io.open(P, "w", encoding="utf-8").write(s)
print("предложение: правок", n)
